('jonglieren', 'Jonglieren', 'ballkontrolle', '🤹', 'E', 'count', 'Ballkontakte am Stück', false, false, '{"bronze":10,"silber":25,"gold":50}'::jsonb, '{"variant":{"bronze":"Mit deinem starken Fuß, der Ball darf einmal aufspringen.","silber":"Ohne Aufspringen, nur Füße.","gold":"Ohne Aufspringen, abwechselnd links und rechts."},"description":"Halte den Ball so lange wie möglich in der Luft. Das schult Ballgefühl und Gleichgewicht.","steps":["Ball mit den Händen fallen lassen und mit dem Spann leicht nach oben spielen.","Fußspitze leicht nach oben ziehen, damit der Ball gerade hochgeht.","Zähle deine Kontakte. Drei Versuche – der beste zählt."],"tips":["Kleine, weiche Kontakte statt kräftiger Tritte.","Blick auf den Ball, Knie locker."],"equipment":"Ball","minutes":10}'::jsonb),
